Set<String> names = new Set<String>{'a'};
System.assert(names.addAll(new Set<String>{'b', 'c'}));
System.assert(names.containsAll(new Set<String>{'a', 'b'}));
System.assert(names.equals(new Set<String>{'c', 'b', 'a'}));
System.assert(names.removeAll(new List<String>{'c'}));
System.assert(names.removeAll(new Set<String>{'b'}));
System.assert(!names.retainAll(new Set<String>{'a'}));
String uuidText = UUID.randomUUID();
UUID parsedUUID = UUID.fromString(uuidText);
System.assertEquals(uuidText, parsedUUID.toString());
Version version = new Version(1, 2, 3);
System.assertEquals(1, version.major());
System.assertEquals(2, version.minor());
System.assertEquals(3, version.patch());
System.assert(new Version(1, 2).compareTo(new Version(2, 0)) < 0);
String fileURL = URL.getFileFieldURL('001B000001DVM9tIAH', 'Body');
System.assert(fileURL.contains('id=001B000001DVM9tIAH'));
System.assert(fileURL.contains('field=Body'));
URL detailed = new URL('https://user:pass@example.test:8443/apex/Page?id=001#top');
System.assertEquals('user:pass', detailed.getUserInfo());
URL sameFile = new URL('https://example.test:8443/apex/Page?id=001#other');
System.assert(detailed.sameFile(sameFile));
URL differentQuery = new URL('https://example.test:8443/apex/Page?id=002#top');
System.assert(!detailed.sameFile(differentQuery));
Type accountType = Type.forName('Account');
System.assertEquals('Account', accountType.getName());

